<script>const buscadorEvento = document.getElementById('buscar-evento'); let temporizadorBusqueda; buscadorEvento?.addEventListener('input', () => { clearTimeout(temporizadorBusqueda); document.getElementById('busqueda-estado').textContent = 'Buscando...'; temporizadorBusqueda = setTimeout(() => { const parametros = new URLSearchParams(window.location.search); const termino = buscadorEvento.value.trim(); termino ? parametros.set('buscar', termino) : parametros.delete('buscar'); window.location.search = parametros.toString(); }, 350); });</script>
